<?php $following=$user?$app->api('companies/'.$data['id'].'/following')['following']:false; ?>
<section class="panel company-profile"><div class="company-cover"><?php if(!empty($data['coverUrl'])): ?><img src="<?= e(safe_url($data['coverUrl'])) ?>" alt="Ảnh bìa công ty"><?php endif; ?></div><div class="company-identity"><div class="company-heading"><span class="company-initial large"><?= e(mb_substr($data['name'],0,2)) ?></span><div><h1><?= e($data['name']) ?></h1><p class="muted"><?= e(implode(' · ',array_filter([$data['industry']??null,$data['sizeRange']??null,$data['address']??null]))) ?></p></div></div><?php if($user): ?><button class="<?= $following?'ghost':'' ?>" data-action="/companies/<?= e($data['id']) ?>/follow" data-method="<?= $following?'DELETE':'POST' ?>" data-reload><?= $following?'Đang theo dõi':'Theo dõi' ?></button><?php endif; ?></div></section>
<div class="company-layout section"><div><section class="panel"><h2>Giới thiệu</h2><p class="prose"><?= nl2br(e($data['description']?:'Công ty chưa cập nhật phần giới thiệu.')) ?></p></section><section class="section"><h2><?= ui_icon('briefcase',20) ?> Vị trí đang tuyển (<?= count($data['jobs']) ?>)</h2><div class="grid cards"><?php foreach($data['jobs'] as $job): require APP_ROOT.'/views/partials/job-card.php'; endforeach; ?></div><?php if(!$data['jobs']): ?><div class="panel empty"><h3>Chưa có vị trí nào</h3><p class="muted">Công ty hiện không có tin tuyển dụng đang mở.</p></div><?php endif; ?></section><?php if($data['posts']): ?><section class="section"><h2>Văn hoá & hoạt động</h2><?php foreach($data['posts'] as $post): ?><article class="panel section"><div class="person-identity"><?= ui_avatar($post['author']['profile']??[],32) ?><strong><?= e($post['author']['profile']['fullName']??'Thành viên') ?></strong></div><p class="prose"><?= nl2br(e($post['content'])) ?></p><a href="/feed?post=<?= e($post['id']) ?>">Xem bài viết →</a></article><?php endforeach; ?></section><?php endif; ?></div><aside><section class="panel"><h2>Thông tin công ty</h2><?php foreach(['industry'=>'Ngành nghề','sizeRange'=>'Quy mô','address'=>'Địa chỉ','foundedYear'=>'Năm thành lập'] as $key=>$label):if(empty($data[$key]))continue; ?><div class="entry"><small class="muted"><?= e($label) ?></small><p><?= e($data[$key]) ?></p></div><?php endforeach; ?><div class="entry"><small class="muted">Người theo dõi</small><p><?= (int)$data['followerCount'] ?></p></div><?php if(!empty($data['website'])): ?><a href="<?= e(safe_url($data['website'])) ?>" target="_blank" rel="noopener">Website công ty ↗</a><?php endif; ?></section></aside></div>